//#region ../../packages/workbuddy-server/src/storage/database-file-logger.ts
/**
* Database File Logger
*
* 将 WorkbuddyDatabaseService 的关键诊断/修复日志持久化到磁盘。
*
* daemon 进程的 stdout 被 RPC 协议占用、stderr 仅保留尾部 80 行，
* 导致 console.log/warn/error 输出的 DB 修复/WAL checkpoint 日志
* 无法事后追溯。本 logger 将这些日志落盘到
* `~/.workbuddy/logs/database/database-<YYYYMMDD>.log`，
* 方便生产环境排查 DB 损坏/修复问题。
*
* 基于 BufferedFileLogger 基础设施，与 MigrationFileLogger 同一模式。
*/
/**
* Database file logger singleton.
*
* - Writes logs to ~/.workbuddy/logs/database/
* - Also mirrors to console for backward compatibility (daemon stderr tail)
*/
var DatabaseFileLogger = class DatabaseFileLogger extends BufferedFileLogger {
	static instance = null;
	constructor() {
		super({
			logDir: require_runtime_context.getWorkbuddyRuntimeLogsDir("database"),
			filePrefix: "database",
			retentionDays: 30
		});
	}
	static getInstance() {
		if (!DatabaseFileLogger.instance) DatabaseFileLogger.instance = new DatabaseFileLogger();
		return DatabaseFileLogger.instance;
	}
};
/** 获取 DatabaseFileLogger 单例 */
function getDatabaseLogger() {
	return DatabaseFileLogger.getInstance();
}
