//#region ../../packages/workbuddy-server/src/storage/sqlite/ghost-cleanup.ts
function cleanupGhostDataAfterWalCheckpoint(dbPath) {
	const rawDb = openWorkbuddyRawSqliteDatabase(dbPath);
	try {
		configureWorkbuddySqliteConnection(rawDb);
		const db = createWorkbuddyDrizzleDatabase(rawDb);
		const now = Date.now();
		const emptyResult = db.update(sessions).set({
			deletedAt: now,
			updatedAt: now
		}).where(sql`${sessions.deletedAt} IS NULL AND (${sessions.cwd} IS NULL OR TRIM(${sessions.cwd}) = '')`).run();
		const emptyCwdSessions = Number(emptyResult.changes ?? 0);
		const sessionIdsToClean = db.select({
			id: sessions.id,
			cwd: sessions.cwd
		}).from(sessions).where(sql`${sessions.deletedAt} IS NULL AND ${sessions.cwd} IS NOT NULL AND TRIM(${sessions.cwd}) != ''`).all().filter((session) => !fs.existsSync(session.cwd)).map((session) => session.id);
		let missingCwdSessions = 0;
		if (sessionIdsToClean.length > 0) {
			const result = db.update(sessions).set({
				deletedAt: now,
				updatedAt: now
			}).where(inArray(sessions.id, sessionIdsToClean)).run();
			missingCwdSessions = Number(result.changes ?? 0);
		}
		const automationsWithCwds = db.select({
			id: automations.id,
			cwds: automations.cwds
		}).from(automations).where(sql`${automations.deletedAt} IS NULL AND ${automations.cwds} IS NOT NULL AND TRIM(${automations.cwds}) != '' AND TRIM(${automations.cwds}) != '[]'`).all();
		const automationIdsToClean = [];
		for (const automation of automationsWithCwds) try {
			const cwdList = JSON.parse(automation.cwds);
			if (!Array.isArray(cwdList) || cwdList.length === 0) {
				automationIdsToClean.push(automation.id);
				continue;
			}
			if (cwdList.every((cwd) => typeof cwd === "string" && !fs.existsSync(cwd))) automationIdsToClean.push(automation.id);
		} catch {
			automationIdsToClean.push(automation.id);
		}
		let missingCwdAutomations = 0;
		if (automationIdsToClean.length > 0) {
			const result = db.update(automations).set({
				deletedAt: now,
				updatedAt: now
			}).where(inArray(automations.id, automationIdsToClean)).run();
			missingCwdAutomations = Number(result.changes ?? 0);
		}
		const runIdsToClean = db.select({
			threadId: automationRuns.threadId,
			sourceCwd: automationRuns.sourceCwd
		}).from(automationRuns).where(sql`${automationRuns.sourceCwd} IS NOT NULL AND TRIM(${automationRuns.sourceCwd}) != ''`).all().filter((run) => run.sourceCwd !== null && !fs.existsSync(run.sourceCwd)).map((run) => run.threadId);
		let missingSourceCwdRuns = 0;
		if (runIdsToClean.length > 0) {
			const result = db.delete(automationRuns).where(inArray(automationRuns.threadId, runIdsToClean)).run();
			missingSourceCwdRuns = Number(result.changes ?? 0);
		}
		return {
			emptyCwdSessions,
			missingCwdSessions,
			missingCwdAutomations,
			missingSourceCwdRuns
		};
	} finally {
		rawDb.close();
	}
}
