//#region ../../packages/workbuddy-server/src/storage/sqlite/legacy-vscdb-reader.ts
function readLegacyVscdbSessionPayloads(vscdbPath) {
	let vscdb;
	try {
		vscdb = openWorkbuddyRawSqliteDatabase(vscdbPath, { readonly: true });
		const rows = vscdb.prepare("SELECT value FROM ItemTable WHERE key LIKE 'session:%'").all();
		const payloads = [];
		for (const row of rows) {
			if (!row.value) continue;
			try {
				payloads.push(JSON.parse(row.value));
			} catch {}
		}
		return payloads;
	} finally {
		vscdb?.close();
	}
}
