		try {
			const stat = fs.statSync(walPath);
			if (stat.size < WorkbuddyDatabaseService.MIN_WAL_WITH_DATA) return null;
			const fd = fs.openSync(walPath, "r");
			try {
				const magicBuf = Buffer.alloc(4);
				fs.readSync(fd, magicBuf, 0, 4, 0);
				const magic = magicBuf.readUInt32BE(0);
				if (magic === WorkbuddyDatabaseService.WAL_MAGIC_1 || magic === WorkbuddyDatabaseService.WAL_MAGIC_2) return null;
				return {
					walPath,
					walSize: stat.size
				};
			} finally {
				fs.closeSync(fd);
			}
		} catch {
			return null;
		}
