async function getExpertRanking(deps, options) {
	try {
		const session = deps.authenticationManager.currentSessionSubject.getValue();
		if (!session?.auth?.accessToken) return null;
		const endpoint = deps.productManager.getEndpoint();
		if (!endpoint) return null;
		const { account, auth } = session;
		const searchParams = new URLSearchParams();
		if (options?.limit && Number.isFinite(options.limit) && options.limit > 0) searchParams.set("limit", String(Math.floor(options.limit)));
		if (options?.enterpriseId) searchParams.set("enterpriseId", options.enterpriseId);
		if (options?.days && Number.isFinite(options.days) && options.days > 0) searchParams.set("days", String(Math.floor(options.days)));
		if (options?.force) searchParams.set("force", "true");
		const rankingUrl = `${endpoint}/console/expert/ranking${searchParams.toString() ? `?${searchParams.toString()}` : ""}`;
		const headers = {
			Accept: "application/json",
			Authorization: `Bearer ${auth.accessToken}`,
			"Content-Type": "application/json"
		};
		if (account?.uid) headers["X-User-Id"] = account.uid;
		if (account?.enterpriseId) {
			headers["X-Enterprise-Id"] = account.enterpriseId;
			headers["X-Tenant-Id"] = account.enterpriseId;
		}
		if (account?.departmentFullName) headers["X-Department-Info"] = account.departmentFullName;
		if (auth.domain) headers["X-Domain"] = auth.domain;
		const response = await deps.fetch(rankingUrl, { headers });
		if (!response.ok) return null;
		const data = await response.json();
		if (data.code !== 0 || !data.data) return null;
		const normalizedItems = Array.isArray(data.data.items) ? data.data.items : Array.isArray(data.data.experts) ? data.data.experts : [];
		return {
			items: normalizedItems,
			total: data.data.total ?? normalizedItems.length,
			updateTime: data.data.updateTime ?? Date.now()
		};
	} catch (error) {
		(deps.logger ?? console).error("[ExpertService] expert ranking failed:", String(error));
		return null;
	}
}
