	const incomingEn = typeof params?.description_en === "string" ? params.description_en.trim() : "";
	if (!matchName) return 0;
	if (!incomingZh && !incomingEn) return 0;
	if (!node_fs.existsSync(userSkillsDir)) return 0;
	const target = String(matchName).trim().toLowerCase();
	let updated = 0;
	try {
		const entries = node_fs.readdirSync(userSkillsDir, { withFileTypes: true });
		for (const entry of entries) {
			if (!entry.isDirectory()) continue;
			const metaPath = node_path.join(userSkillsDir, entry.name, BUILTIN_MARKET_META_FILE);
			if (!node_fs.existsSync(metaPath)) continue;
			let raw;
			try {
				raw = JSON.parse(node_fs.readFileSync(metaPath, "utf-8"));
			} catch {
				continue;
			}
			if (raw.source !== "marketplace") continue;
			const metaName = typeof raw.name === "string" ? raw.name.trim().toLowerCase() : "";
			if (!metaName || metaName !== target) continue;
			const existingZh = typeof raw.description_zh === "string" ? raw.description_zh.trim() : "";
			const existingEn = typeof raw.description_en === "string" ? raw.description_en.trim() : "";
			let dirty = false;
			if (!existingZh && incomingZh) {
				raw.description_zh = incomingZh;
				dirty = true;
			}
			if (!existingEn && incomingEn) {
				raw.description_en = incomingEn;
				dirty = true;
			}
			if (!dirty) continue;
			try {
				node_fs.writeFileSync(metaPath, JSON.stringify(raw, null, 2));
				updated++;
				console.log(`${TAG$20} [builtinMarketBackfillDescription] backfilled description for "${entry.name}" (name="${matchName}")`);
			} catch (error) {
				console.warn(`${TAG$20} [builtinMarketBackfillDescription] write failed:`, String(error));
			}
		}
	} catch (error) {
		console.error(`${TAG$20} builtinMarketBackfillDescription failed:`, String(error));
	}
