async function handleSkillImport(skillsService, params, deps, policyService) {
	try {
		await policyService?.assertOperationAllowed({ surface: "main-skill-import" });
	} catch (error) {
		return policyErrorToImportResponse(error);
	}
	try {
		let selectedPath;
		if (params.folderPath) selectedPath = params.folderPath;
		else selectedPath = await pickSkillSource(deps.dialog, deps.platform);
		if (!selectedPath) return {
			success: false,
			error: "No file or folder selected"
		};
		const isZip = selectedPath.toLowerCase().endsWith(".zip");
		const sourceFolderPath = isZip ? await extractZipToTempDir(selectedPath) : selectedPath;
		try {
			if (policyService) try {
				const sizeBytes = await computePackageSizeBytes(sourceFolderPath);
				await policyService.assertWithinSizeLimit(sizeBytes, { surface: "main-skill-import" });
			} catch (sizeError) {
				return policyErrorToImportResponse(sizeError);
			}
			return await skillsService.installSkillByPath({
				source: params.source,
				folderPath: sourceFolderPath,
				cwd: params.cwd,
				securityCheck: params.securityCheck,
				appKey: params.appKey,
				scanSourcePath: isZip ? selectedPath : void 0,
				overwrite: params.overwrite
			});
		} finally {
			if (isZip) await node_fs_promises.rm(sourceFolderPath, {
				recursive: true,
				force: true
			}).catch(() => {});
		}
	} catch (error) {
		return {
			success: false,
			error: error instanceof Error ? error.message : String(error)
		};
	}
}
