async function pickSkillSource(dialog, platform) {
	if (platform === "darwin") {
		const result = await dialog.showOpenDialog({
			title: "Import Skill",
			properties: ["openFile", "openDirectory"],
			filters: [{
				name: "Skill Package",
				extensions: ["zip"]
			}]
		});
		if (result.canceled || !result.filePaths[0]) return;
		return result.filePaths[0];
	}
	const fileResult = await dialog.showOpenDialog({
		title: "Import Skill",
		properties: ["openFile"],
		filters: [{
			name: "Skill Package",
			extensions: ["zip", "md"]
		}]
	});
	if (fileResult.canceled || !fileResult.filePaths[0]) return;
	const selectedFile = fileResult.filePaths[0];
	if (selectedFile.toLowerCase().endsWith(".md")) return node_path.dirname(selectedFile);
	return selectedFile;
}
async function extractZipToTempDir(zipPath) {
	const tempDir = node_path.join(node_os.tmpdir(), `workbuddy-skill-${Date.now()}`);
	await node_fs_promises.mkdir(tempDir, { recursive: true });
	new import_adm_zip.default(zipPath).extractAllTo(tempDir, true);
	return locateSkillRoot(tempDir);
}
async function locateSkillRoot(extractedDir) {
	let currentDir = extractedDir;
	for (let depth = 0; depth < 2; depth++) {
		if (node_fs.existsSync(node_path.join(currentDir, "SKILL.md"))) return currentDir;
		const subDirs = (await node_fs_promises.readdir(currentDir, { withFileTypes: true })).filter((e) => e.isDirectory() && e.name !== "__MACOSX");
		if (subDirs.length !== 1) break;
		currentDir = node_path.join(currentDir, subDirs[0].name);
	}
	throw new Error("SKILL.md not found in zip archive");
}
async function handleSkillInstallFromUrl(skillsService, securityClientRef, params, fetchFn, deps, policyService) {
	const requestedSkillName = params.skillName?.trim();
	if (!requestedSkillName) return {
		success: false,
		errorKey: "invalidSkillId",
		errorMessage: "Missing required skill identifier"
	};
	const downloadInput = params.downloadUrl?.trim();
	if (!downloadInput) return {
		success: false,
		errorKey: "invalidDownloadUrl",
		errorMessage: "Missing skill package path or URL"
	};
	try {
		let localFilePath;
		let prepareSkillName = requestedSkillName;
		let warningKey;
		let warningMessage;
		if (/^https:\/\//i.test(downloadInput)) {
			const prepareResult = await handleSkillPrepareFromUrl({
				skillName: requestedSkillName,
				downloadUrl: downloadInput
			}, fetchFn, policyService);
			if (!prepareResult.success) return {
				success: false,
				errorKey: prepareResult.errorKey || "installFromUrlFailed",
				errorMessage: prepareResult.errorMessage || "Failed to download skill package"
			};
			localFilePath = prepareResult.downloadedFilePath;
			prepareSkillName = prepareResult.skillName || requestedSkillName;
			warningKey = prepareResult.warningKey;
			warningMessage = prepareResult.warningMessage;
		} else localFilePath = downloadInput;
		if (params.appKey && !securityClientRef.current) securityClientRef.current = new SkillSecurityClient({ appKey: params.appKey });
		const importResult = await handleSkillImport(skillsService, {
			source: "userSettings",
			folderPath: localFilePath,
			overwrite: params.overwrite,
			securityCheck: params.securityCheck ?? true,
			appKey: params.appKey
		}, deps, policyService);
		if (!importResult.success) {
			let errorKey;
			if (importResult.error?.includes("already exists")) errorKey = "duplicateSkillName";
			else if (importResult.error?.includes("SKILL.md")) errorKey = "skillFileMissing";
			else if (importResult.error?.includes("security_check_blocked")) errorKey = "security_check_blocked";
			return {
				success: false,
				errorKey,
				errorMessage: importResult.error || "Failed to import skill package",
				warningKey,
				warningMessage,
				skillName: errorKey === "duplicateSkillName" ? importResult.skillName || prepareSkillName : void 0,
				preCheck: importResult.preCheck
			};
		}
		const installedSkillName = importResult.skillName || prepareSkillName;
		const activatedSkillId = installedSkillName.toLowerCase().replace(/\s+/g, "-").trim();
		const installedFilePath = (await skillsService.getSkillList({ global: true })).results.find((s) => s.name === installedSkillName)?.filePath;
		return {
			success: true,
			warningKey,
			warningMessage,
			importedSkillIds: [activatedSkillId],
			activatedSkillId,
			skillName: installedSkillName,
			installedFilePath
		};
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		deps.logger?.error("[SkillHandler][installFromUrl] failed:", message);
		return {
			success: false,
			errorKey: "installFromUrlFailed",
			errorMessage: message
		};
	}
}
var SKILL_DOWNLOAD_TEMP_PREFIX = "workbuddy-skill-download-";
var SKILL_DOWNLOAD_MAX_BYTES = 50 * 1024 * 1024;
var SKILL_DOWNLOAD_TIMEOUT_MS = 60 * 1e3;
var SKILL_DOWNLOAD_ALLOWED_EXTS = new Set([".zip", ".md"]);
