	get(key) {
		return this.config[key] ?? null;
	}
	/**
	* 设置配置值
	*/
	set(key, value) {
		this.config[key] = value;
		this.save();
	}
	/**
	* 获取全部配置
	*/
	getAll() {
		return { ...this.config };
	}
