		generateWxMPQRCode: async (bizType, shareCode, shareUrl, shareTitle, shareCover) => {
			try {
				const headers = buildShareAuthHeaders(deps);
				if (!headers) return {
					data: null,
					error: "Not logged in"
				};
				const endpoint = deps.productManager.getEndpoint();
				if (!endpoint) return {
					data: null,
					error: "No endpoint"
				};
				const json = await (await deps.fetch(`${endpoint}/v2/as/p/wxaqrcode/qrcode`, {
					method: "POST",
					headers,
					body: JSON.stringify({
						scene_type: WxaQrcodeSceneTypes.SHARE_TRANSIT,
						params: {
							biz_type: bizType,
							share_code: shareCode,
							share_url: shareUrl,
							share_title: shareTitle,
							share_cover: shareCover
						}
					})
				})).json();
				if (json?.code && typeof json.code === "number" && json.code !== 0) return {
					data: null,
					error: json.message || json.msg || "Unknown error"
				};
				const raw = json?.data ?? json;
				if (!raw?.cos_url) return {
					data: null,
					error: "Empty wxa qrcode response"
				};
				return {
					data: {
						scene: raw.scene,
						sceneType: raw.scene_type,
						params: raw.params,
						cosUrl: raw.cos_url,
						cached: !!raw.cached,
						dataUrl: raw.data_url
					},
					error: null
				};
			} catch (error) {
				logger.error("[ShareFacade] generateWxMPQRCode failed:", error);
				return {
					data: null,
					error: error instanceof Error ? error.message : String(error)
				};
			}
		},
