		uploadTaskFile: async (params) => {
			try {
				const headers = buildShareAuthHeaders(deps, { includeJsonContentType: false });
				if (!headers) return {
					success: false,
					error: "Not logged in"
				};
				const endpoint = deps.productManager.getEndpoint();
				if (!endpoint) return {
					success: false,
					error: "No endpoint"
				};
				const filePath = normalizeShareLocalPath(params.filePath);
				const actualFileName = params.fileName || node_path.basename(filePath);
				const remotePath = extractShareRemotePath(filePath);
				await node_fs.promises.access(filePath, node_fs.constants.R_OK);
				const fileBuffer = await node_fs.promises.readFile(filePath);
				const formData = new FormData();
				const fileBlob = new Blob([fileBuffer]);
				formData.append("file", fileBlob, actualFileName);
				if (params.fileName) formData.append("fileName", params.fileName);
				formData.append("filePath", remotePath);
				const json = await (await deps.fetch(`${endpoint}/v2/as/tasks/share/prepare/${encodeURIComponent(params.prepareId)}/upload`, {
					method: "POST",
					headers,
					body: formData
				})).json();
				if (json?.code === 0 && json?.data) return {
					success: true,
					artifact: json.data.artifact
				};
				return {
					success: false,
					error: json?.msg || json?.data?.error || "Upload share task file failed",
					code: json?.code
				};
			} catch (error) {
				logger.error("[ShareFacade] share uploadTaskFile failed:", error);
				return {
					success: false,
					error: error instanceof Error ? error.message : String(error),
					code: error?.code
				};
			}
		},
