var SMH_URL_TTL_MS = 3600 * 1e3;
var CACHE_EXPIRE_BUFFER_MS = 60 * 1e3;
/**
* 处理 get_artifact 命令：
*   1. 查本地 SQLite 缓存（按 file_path，跨会话共享）
*      - 命中且 (mtime, size) 未变、URL 未过期 → 直接返 cached=true
*   2. 否则上传 SMH，写缓存，返回新的 downloadUrl
*
* ⚠️ 不做云端 callback：Web 直接通过 replyChannel 拿结果，云端不感知本次上传。
* （原 §5.2 POST /callbacks/artifact-uploaded 已废弃，见文末注释）
*/
async function handleGetArtifact(ctx, cmd) {
	const filePath = cmd.filePath;
	const commandId = cmd.commandId;
	ctx.logger.info(`[EdgeSync] §7 ARTIFACT: file=${filePath} commandId=${commandId}`);
	const homeDir = node_os.homedir();
	const homeDirWithSep = homeDir.endsWith(node_path.sep) ? homeDir : homeDir + node_path.sep;
	const resolvedPath = node_path.resolve(filePath);
	if (filePath.includes("..")) {
		ctx.logger.warn("[EdgeSync] §7 ARTIFACT denied: path traversal detected");
		return {
			requestId: commandId,
			status: "failed"
		};
	}
	if (resolvedPath !== homeDir && !resolvedPath.startsWith(homeDirWithSep)) {
		ctx.logger.warn("[EdgeSync] §7 ARTIFACT denied: outside home directory");
		return {
			requestId: commandId,
			status: "failed"
		};
	}
	try {
		const realPath = node_fs.realpathSync(resolvedPath);
		if (realPath !== homeDir && !realPath.startsWith(homeDirWithSep)) {
			ctx.logger.warn("[EdgeSync] §7 ARTIFACT denied: symlink escape");
			return {
				requestId: commandId,
				status: "failed"
			};
		}
	} catch {}
	const relativeToHome = resolvedPath.slice(homeDirWithSep.length);
	if ([
		".ssh",
		".gnupg",
		".aws",
		".kube",
		".docker",
		".npmrc",
		".netrc",
		".gitcredentials",
		".config/gcloud"
	].some((root) => relativeToHome === root || relativeToHome.startsWith(root + node_path.sep))) {
		ctx.logger.warn("[EdgeSync] §7 ARTIFACT denied: sensitive directory");
		return {
			requestId: commandId,
			status: "failed"
		};
	}
	if (!node_fs.existsSync(filePath)) {
		ctx.logger.warn(`[EdgeSync] §7 ARTIFACT missing: ${filePath}`);
		return {
			requestId: commandId,
			status: "missing"
		};
	}
	const stat = node_fs.statSync(filePath);
	if (stat.size > 100 * 1024 * 1024) {
		ctx.logger.warn(`[EdgeSync] §7 ARTIFACT too large: ${stat.size}`);
		return {
			requestId: commandId,
			status: "too_large",
			size: stat.size
		};
	}
	const now = Date.now();
	const cached = ctx.getArtifactCache(filePath);
	if (cached && cached.mtime_ms === stat.mtimeMs && cached.size === stat.size && cached.expires_at - CACHE_EXPIRE_BUFFER_MS > now && cached.download_url) {
		ctx.logger.info(`[EdgeSync] §7 ARTIFACT cache hit: file=${filePath} expiresIn=${cached.expires_at - now}ms`);
		return {
			requestId: commandId,
			status: "success",
			cached: true,
			downloadUrl: cached.download_url,
			smhPath: cached.smh_path,
			fileHash: cached.file_hash,
			size: cached.size,
			contentType: cached.content_type || void 0,
			expiresAt: cached.expires_at
		};
	}
	try {
		const fileName = node_path.basename(filePath);
		const fileHash = await new Promise((resolve, reject) => {
			const hash = node_crypto.createHash("sha256");
			const stream = node_fs.createReadStream(filePath);
			stream.on("data", (chunk) => hash.update(chunk));
			stream.on("end", () => resolve(`sha256:${hash.digest("hex")}`));
			stream.on("error", reject);
		});
		const formData = new FormData();
		formData.append("file", await node_fs.openAsBlob(filePath), fileName);
		formData.append("fileName", fileName);
		formData.append("filePath", `.conversation-sync/${cmd.conversationId || "unknown"}/${fileName}`);
		formData.append("createShare", "true");
		const uploadRaw = await ctx.deps.http.post("/v2/as/netdisk/upload", formData);
		const uploadResult = ctx.unwrapResponse(uploadRaw, "NETDISK-UPLOAD");
		const downloadUrl = uploadResult?.downloadUrl || uploadResult?.shareUrl || "";
		if (!downloadUrl) {
			ctx.logger.warn(`[EdgeSync] §7 ARTIFACT upload returned empty downloadUrl: rawKeys=${Object.keys(uploadResult || {}).join(",")}`);
			return {
				requestId: commandId,
				status: "failed",
				errorMsg: "upload response missing downloadUrl"
			};
		}
		const contentType = guessContentType(fileName);
		const smhPath = `.conversation-sync/${ctx.deps.getAccount()?.uid || "unknown"}/${cmd.conversationId || "unknown"}/${fileHash}_${fileName}`;
		const expiresAt = typeof uploadResult?.expiresAt === "number" ? uploadResult.expiresAt : now + SMH_URL_TTL_MS;
		ctx.upsertArtifactCache({
			file_path: filePath,
			mtime_ms: stat.mtimeMs,
			size: stat.size,
			file_hash: fileHash,
			download_url: downloadUrl,
			smh_path: smhPath,
			content_type: contentType,
			expires_at: expiresAt
		});
		ctx.logger.info(`[EdgeSync] §7 ARTIFACT uploaded: ${fileName} → ${downloadUrl.slice(0, 60)}... expiresAt=${expiresAt}`);
		return {
			requestId: commandId,
			status: "success",
			cached: false,
			downloadUrl,
			smhPath,
			fileHash,
			size: stat.size,
			contentType,
			expiresAt
		};
	} catch (err) {
		ctx.logger.warn(`[EdgeSync] §7 ARTIFACT upload failed: ${err?.message || String(err)}`);
		return {
			requestId: commandId,
			status: "failed",
			errorMsg: err?.message || String(err)
		};
	}
}
/** 根据文件扩展名猜测 MIME 类型 */
function guessContentType(fileName) {
	return {
		".pdf": "application/pdf",
		".png": "image/png",
		".jpg": "image/jpeg",
		".gif": "image/gif",
		".svg": "image/svg+xml",
		".html": "text/html",
		".js": "application/javascript",
		".ts": "text/typescript",
		".json": "application/json",
		".md": "text/markdown",
		".txt": "text/plain",
		".zip": "application/zip"
	}[node_path.extname(fileName).toLowerCase()] || "application/octet-stream";
}
/**
* 遍历 contentBlocks，将远程图片 URI 下载并转为 base64 data，
* 同时写入 blob_id → cos_uri 映射供 get_page 回放时还原。
*
* 改写是 in-place 的（直接 mutate contentBlocks 数组元素）。
* 下载失败的图片保留原样（降级：前端拿到 uri 自己兜底渲染）。
*/
async function localizeRemoteImages(contentBlocks, sessionId, ctx) {
	for (let i = 0; i < contentBlocks.length; i++) {
		const block = contentBlocks[i];
		if (block.type !== "image") continue;
		const uri = block.uri;
		if (!uri || !isRemoteUrl(uri)) continue;
		if (block.data) continue;
		try {
			edgeLog("IMAGE_DOWNLOAD_START", `uri=${uri.slice(0, 120)} sid=${sessionId}`);
			const response = await fetch(uri);
			if (!response.ok) {
				edgeLog("IMAGE_DOWNLOAD_FAIL", `uri=${uri.slice(0, 120)} status=${response.status}`);
				continue;
			}
			const buffer = Buffer.from(await response.arrayBuffer());
			if (buffer.length > 10 * 1024 * 1024) {
				edgeLog("IMAGE_DOWNLOAD_SKIP", `uri=${uri.slice(0, 120)} size=${buffer.length} reason=too_large`);
				continue;
			}
			const blobId = node_crypto.createHash("sha256").update(buffer).digest("hex");
			const base64Data = buffer.toString("base64");
			const declaredMime = block.mimeType;
			const headerMime = response.headers.get("content-type")?.split(";")[0]?.trim();
			const mime = declaredMime || headerMime || "image/png";
			ctx.saveImageMapping(blobId, uri, sessionId);
			contentBlocks[i] = {
				type: "image",
				data: base64Data,
				mimeType: mime,
				uri
			};
			edgeLog("IMAGE_DOWNLOAD_OK", `uri=${uri.slice(0, 80)} blobId=${blobId.slice(0, 12)} size=${buffer.length} sid=${sessionId}`);
		} catch (err) {
			edgeLog("IMAGE_DOWNLOAD_ERROR", `uri=${uri?.slice(0, 120)} err=${err?.message || String(err)}`);
		}
	}
}
/** 判断是否为远程 URL（http/https） */
function isRemoteUrl(uri) {
	return uri.startsWith("http://") || uri.startsWith("https://");
}
/**
* 遍历 notifications，将 user message content 中的 image_blob_ref
* 通过映射表还原为 { type:'image', uri, mimeType }，让前端直接用 uri 渲染。
*
* 遍历范围：只处理 user_message_chunk / user_message 类型的 notification，
* 其余（agent_message_chunk / tool_use 等）不含用户图片，跳过。
*/
function rebindImageBlobRefs(notifications, ctx) {
	for (const notif of notifications) {
		const params = notif.params;
		if (!params) continue;
		const update = params.update;
		if (!update) continue;
		const sessionUpdate = update.sessionUpdate;
		if (sessionUpdate === "user_message_chunk" || sessionUpdate === "user_message") rebindContentImages(update, ctx);
		const extra = (params._meta?.["codebuddy.ai"])?.extra;
		if (extra?.sourceContentBlocks && Array.isArray(extra.sourceContentBlocks)) rebindBlockArray(extra.sourceContentBlocks, ctx);
	}
}
/**
* 处理单条 notification 的 content 字段（可能是对象/数组/嵌套）。
*/
function rebindContentImages(update, ctx) {
	const content = update.content;
	if (Array.isArray(content)) {
		rebindBlockArray(content, ctx);
		return;
	}
	if (content && typeof content === "object") {
		const block = content;
		if (block.type === "image_blob_ref") {
			const uri = ctx.getImageUri(block.blob_id);
			if (uri) update.content = {
				type: "image",
				uri,
				mimeType: block.mime || "image/png"
			};
		}
	}
}
/**
* 遍历 block 数组，将 image_blob_ref 替换为 { type:'image', uri }。
* in-place 修改。
*/
function rebindBlockArray(blocks, ctx) {
	for (let i = 0; i < blocks.length; i++) {
		const block = blocks[i];
		if (!block || block.type !== "image_blob_ref") continue;
		const blobId = block.blob_id;
		if (!blobId) continue;
		const uri = ctx.getImageUri(blobId);
		if (uri) blocks[i] = {
			type: "image",
			uri,
			mimeType: block.mime || "image/png"
		};
	}
}
